code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long minVal = Long.MAX_VALUE; int minIdx = 0;
            for (int i = 0; i < n; i++) {
                long val = sc.nextLong();
                if (i == 0 || val < minVal) { minVal = val; minIdx = i; }
            }
            System.out.println(minVal + "\n" + minIdx);
        }
    }
}

